// 01: parse the Telegram update, run authorization, decide top-level action.
// Outputs ONE item with normalized fields and a chosen `action`:
//   denied | send_text | render_dashboard | save_explicit | ai_classify
//   command_categories | command_category_add | command_set_goal
//   command_delete_last | pending_reply_pick | todo

const raw = $input.first().json;
const msg = raw.message || raw.edited_message;
if (!msg) return [];

const isEdit = !!raw.edited_message;
const chatId = String(msg.chat.id);
const userId = String(msg.from.id);
const messageId = String(msg.message_id);
const text = (msg.text || '').trim();

const nowLocal = new Date(
  new Date().toLocaleString('en-US', { timeZone: $env.GENERIC_TIMEZONE || 'Europe/Warsaw' })
);
const y = nowLocal.getFullYear();
const m = String(nowLocal.getMonth() + 1).padStart(2, '0');
const d = String(nowLocal.getDate()).padStart(2, '0');
const todayDate = `${y}-${m}-${d}`;

const allowedUsers = ($env.AUTHORIZED_TELEGRAM_USER_IDS || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const allowedChats = ($env.AUTHORIZED_TELEGRAM_CHAT_IDS || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const hasAllowlist = allowedUsers.length > 0 || allowedChats.length > 0;
const authorized = hasAllowlist
  && (allowedUsers.includes(userId) || allowedChats.includes(chatId));

const base = { chatId, userId, messageId, text, isEdit, todayDate, authorized };

if (!authorized) {
  return [{ json: { ...base, action: 'denied', replyText: 'Access denied.' } }];
}

if (text.startsWith('/')) {
  const parts = text.split(/\s+/);
  const cmd = parts[0].split('@')[0].toLowerCase();
  const args = text.slice(parts[0].length).trim();

  if (cmd === '/help' || cmd === '/start') {
    return [{ json: { ...base, action: 'send_text', replyText:
`Time Tracker

Formats:
  0855-0955 [FRIENDS] разговор с другом
  1300-1400 интервью
  20 мин отвечал в Telegram

Commands:
  /dashboard         show current dashboard
  /today /week       compact day/week view
  /categories        list active categories
  /category_add CODE | Name | Description
  /goal_week CODE | hours
  /goal_day CODE | hours
  /delete_last       delete last entry
  /edit_last <text>  replace last entry
  /dashboard_compact /dashboard_full
  /help              this message

When the bot asks a clarification question, reply with:
  1 / 2 / ... — pick the suggested option by number
  [CODE]      — pick by category code directly
  <new text>  — replace the question with a new detailed entry`,
    } }];
  }

  if (cmd === '/dashboard' || cmd === '/today' || cmd === '/week') {
    return [{ json: { ...base, action: 'render_dashboard', dashboardScope: cmd.slice(1) } }];
  }

  if (cmd === '/categories') {
    return [{ json: { ...base, action: 'command_categories' } }];
  }

  if (cmd === '/category_add') {
    const argParts = args.split('|').map(s => s.trim());
    const code = argParts[0] || '';
    const name = argParts[1] || '';
    const description = argParts[2] || null;
    if (!/^[A-Z_][A-Z0-9_]*$/.test(code) || !name) {
      return [{ json: { ...base, action: 'send_text', replyText:
`Использование:
  /category_add CODE | Name | Description

CODE — заглавные буквы и подчёркивания, начинается с буквы или _.
Например: /category_add NEW_PROJECT | Новый проект | Работа над X` } }];
    }
    return [{ json: { ...base, action: 'command_category_add',
      catCode: code, catName: name, catDescription: description } }];
  }

  if (cmd === '/goal_week' || cmd === '/goal_day') {
    const argParts = args.split('|').map(s => s.trim());
    const code = argParts[0] || '';
    const hoursStr = argParts[1] || '';
    if (!/^[A-Z_][A-Z0-9_]*$/.test(code) || !/^\d+(\.\d+)?$/.test(hoursStr)) {
      return [{ json: { ...base, action: 'send_text', replyText:
`Использование:
  ${cmd} CODE | hours

Пример: ${cmd} JOB_SEARCH | 20` } }];
    }
    const hours = parseFloat(hoursStr);
    if (!(hours > 0) || hours > 24 * 7) {
      return [{ json: { ...base, action: 'send_text',
        replyText: 'Hours must be > 0 and <= 168 (one week).' } }];
    }
    const goalMinutes = Math.round(hours * 60);
    const goalType = cmd === '/goal_week' ? 'weekly' : 'daily';
    let goalDateFrom, goalDateTo;
    const fmt = (dt) => `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
    if (goalType === 'weekly') {
      const today = new Date(`${todayDate}T00:00:00`);
      const dow = today.getDay();
      const offsetToMonday = (dow + 6) % 7;
      const monday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - offsetToMonday);
      const sunday = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + 6);
      goalDateFrom = fmt(monday);
      goalDateTo = fmt(sunday);
    } else {
      goalDateFrom = todayDate;
      goalDateTo = todayDate;
    }
    return [{ json: { ...base, action: 'command_set_goal',
      goalType, goalCode: code, goalMinutes, goalDateFrom, goalDateTo } }];
  }

  if (cmd === '/delete_last') {
    return [{ json: { ...base, action: 'command_delete_last' } }];
  }

  if (cmd === '/edit_last') {
    const editText = args.trim();
    if (!editText) {
      return [{ json: { ...base, action: 'send_text', replyText:
`Использование:
  /edit_last <new text>

Пример:
  /edit_last 0900-1000 [PROJECT_A] звонок по задаче` } }];
    }
    const newBase = { ...base, text: editText, lookup_mode: 'last_confirmed' };
    const explicit = parseExplicitRange(editText, todayDate);
    if (explicit) return [{ json: { ...newBase, action: 'save_explicit', slots: [explicit] } }];
    return [{ json: { ...newBase, action: 'ai_classify' } }];
  }

  return [{ json: { ...base, action: 'todo',
    replyText: `Command ${cmd} is recognized but not wired up in this workflow yet. See README "Next steps".` } }];
}

// Pending-clarification picks: a single digit or a single [CODE] alone.
if (/^[1-9]$/.test(text)) {
  return [{ json: { ...base, action: 'pending_reply_pick',
    pickKind: 'digit', pickIndex: parseInt(text, 10), pickCode: '' } }];
}
const codeOnly = /^\[([A-Z_][A-Z0-9_]*)\]$/.exec(text);
if (codeOnly) {
  return [{ json: { ...base, action: 'pending_reply_pick',
    pickKind: 'code', pickIndex: 0, pickCode: codeOnly[1] } }];
}

// Edited Telegram message: tag the save with a by-message-id lookup so
// node 14 can mark the originally-stored batch as replaced.
const editLookup = isEdit ? {
  lookup_mode: 'by_message_id',
  lookup_message_id: messageId,
} : {};

const explicit = parseExplicitRange(text, todayDate);
if (explicit) {
  return [{ json: { ...base, ...editLookup, action: 'save_explicit', slots: [explicit] } }];
}

return [{ json: { ...base, ...editLookup, action: 'ai_classify' } }];

// ---------------------------------------------------------------------
// ---------------------------------------------------------------------
function parseExplicitRange(rawText, today) {
  const codeRe = /\[([A-Z_][A-Z0-9_]*)\]/;
  const codeMatch = codeRe.exec(rawText);
  if (!codeMatch) return null;
  const code = codeMatch[1];
  const stripped = rawText.replace(codeMatch[0], ' ').replace(/\s+/g, ' ').trim();

  // Regex принимает:
  //   14-15           (часы без минут)
  //   14 - 15         (пробелы вокруг тире)
  //   14  -  15       (несколько пробелов)
  //   14:30-15:45     (с двоеточием)
  //   14.30-15.45     (с точкой)
  //   14,30-15,45     (с запятой)
  //   1430-1545       (4 цифры без разделителя)
  //   16-16:30        (смешанный: часы и часы:минуты)
  //   9-10:15         (часы и часы:минуты, неполные)
  const rangeRe = /(?:^|\s)(\d{1,4})(?:\s*[:.,]\s*(\d{1,2}))?\s*-\s*(\d{1,4})(?:\s*[:.,]\s*(\d{1,2}))?(?=\s|$)/;
  const rm = rangeRe.exec(' ' + stripped + ' ');
  if (!rm) return null;

  const startT = parseTimeNumber(rm[1], rm[2]);
  const endT = parseTimeNumber(rm[3], rm[4]);
  if (!startT || !endT) return null;

  const sH = startT.h, sM = startT.m;
  const eH = endT.h, eM = endT.m;

  if (sH > 23 || sM > 59 || eH > 23 || eM > 59) return null;
  if (eH * 60 + eM <= sH * 60 + sM) return null;

  const activity = stripped.replace(rm[0].trim(), '').replace(/\s+/g, ' ').trim() || code;
  return {
    slot_date: today,
    start_time: `${String(sH).padStart(2,'0')}:${String(sM).padStart(2,'0')}`,
    end_time: `${String(eH).padStart(2,'0')}:${String(eM).padStart(2,'0')}`,
    duration_minutes: (eH*60+eM) - (sH*60+sM),
    activity, category_code: code, category_name: null,
    emotional_mark: 'N', confidence: 1, classification_source: 'explicit_user_code',
  };
}

// Helper: интерпретирует число и опциональные минуты как {h, m}
// "14" → 14:00, "14"+"30" → 14:30, "1430" → 14:30, "915" → 9:15, "9" → 9:00
function parseTimeNumber(numStr, minStr) {
  if (minStr !== undefined && minStr !== null) {
    return { h: parseInt(numStr, 10), m: parseInt(minStr, 10) };
  }
  const n = numStr.length;
  if (n <= 2) return { h: parseInt(numStr, 10), m: 0 };
  if (n === 3) return { h: parseInt(numStr.slice(0, 1), 10), m: parseInt(numStr.slice(1), 10) };
  if (n === 4) return { h: parseInt(numStr.slice(0, 2), 10), m: parseInt(numStr.slice(2), 10) };
  return null;
}

// Build the OpenAI Chat Completions API request body.
// Pulls: original message context (from the planner node),
//        active categories (Load Categories), and
//        active examples (Load Examples).

const ctx = $('01 Parse + Authorize + Plan').first().json;
const categories = $('05 Load Categories').all().map(i => i.json);
const examples = $('06 Load Examples').all().map(i => i.json);

const categoriesBlock = categories
  .map(c => `[${c.code}] ${c.name} — ${c.description || ''}`)
  .join('\n');

// Group examples by category, cap per category at MAX_ACTIVE_EXAMPLES_PER_CATEGORY.
const cap = parseInt($env.MAX_ACTIVE_EXAMPLES_PER_CATEGORY || '30', 10);
const grouped = {};
for (const ex of examples) {
  if (!grouped[ex.category_code]) grouped[ex.category_code] = [];
  if (grouped[ex.category_code].length < cap) {
    grouped[ex.category_code].push(ex.example_text);
  }
}
const examplesBlock = Object.entries(grouped)
  .map(([code, exs]) => `${code}:\n  ${exs.map(e => `- ${e}`).join('\n  ')}`)
  .join('\n');

const systemPrompt = `Ты классифицируешь сообщение time tracker.
Твоя задача:
1. Распарсить один или несколько временных слотов.
2. Определить start_time, end_time и duration_minutes.
3. Если есть явный код категории в квадратных скобках — использовать его.
4. Если кода нет — выбрать категорию из списка активных категорий.
5. Если несколько активностей имеют свои длительности — разделить на несколько slots.
6. Если несколько активностей есть, но длительности неясны — needs_clarification=true.
7. Если категория неясна — needs_clarification=true и предложить 2–4 категории.
8. Не придумывать данные.
9. Вернуть только JSON (без префиксов, без markdown).

ВАЖНО про скобки [...]:
- Валидный category_code в скобках — это ТОЛЬКО латинские заглавные буквы и подчёркивания
  (например [JS], [SP], [PROJECT_GL]). Используй как category_code.
- Если в скобках другой текст (русский, нижний регистр, пробелы, например [это быт], 
  [нетворкинг], [время с друзьями]) — это просто заметка пользователя, НЕ category_code.
  Игнорируй такие скобки и классифицируй по смыслу активности.

Если сообщение содержит ДЛИТЕЛЬНОСТЬ без start_time и end_time (например "20 мин X", "1 час Y"),
верни duration_minutes, а start_time/end_time оставь null. 
Система сама рассчитает время от конца последнего confirmed slot за день.

КРИТИЧНО ВАЖНО для паттерна "до HH:MM" или "HH:MM закончил" — это указание КОНЦА слота,
а НЕ точечного момента:
  - "до 12:26 одевался" → end_time="12:26", start_time=null, duration_minutes=0
  - "До 21:00 X" → end_time="21:00", start_time=null, duration_minutes=0
  - "12:30 закончил с Y" → end_time="12:30", start_time=null, duration_minutes=0
  - "до 18:10 разбор интервью" → end_time="18:10", start_time=null, duration_minutes=0
  - "12:26 X" БЕЗ диапазона тоже трактуй как end_time, а НЕ как start_time

ЗАПРЕЩЕНО для таких сообщений возвращать start_time равным end_time или ставить start_time. 
start_time ВСЕГДА null. duration_minutes ВСЕГДА 0.
Система сама вычислит start_time и duration от конца последнего confirmed slot за день.

Если в сообщении только размышление/эмоция без времени и активности (например 
"меня сильно подымает от возможности учить Go", "хочу есть сладкое") — 
верни slot с category_code="RX", duration_minutes=0, start_time=null, end_time=null,
activity = полный текст сообщения, emotional_mark подходящий (+/-/Х/N).
Для RX верни confidence=0.95, needs_clarification=false.

Верни строго JSON в виде:
{
  "slots": [
    {
      "slot_date": "YYYY-MM-DD",
      "start_time": "HH:MM" | null,
      "end_time": "HH:MM" | null,
      "duration_minutes": 0,
      "activity": "activity text",
      "category_code": "CODE",
      "category_name": "Category name",
      "emotional_mark": "N",
      "confidence": 0.95,
      "classification_source": "ai" | "explicit_user_code",
      "needs_clarification": false,
      "clarification_question": "",
      "suggested_categories": []
    }
  ]
}`;

const userPrompt = `Активные категории:
${categoriesBlock}

Примеры классификации:
${examplesBlock}

Текущее сообщение: ${ctx.text}
Текущая дата: ${ctx.todayDate}`;

return [{
  json: {
    ...ctx,
    aiBody: {
      model: $env.AI_MODEL || 'gpt-4o-mini',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      max_tokens: 4096,
      // Force the model to emit a single JSON object (gpt-4o-mini and
      // gpt-4.1-mini both support this; older 3.5 does not).
      response_format: { type: 'json_object' },
    },
  },
}];

// Parse the OpenAI Chat Completions response, validate slots, also
// pull suggested_categories from the first ambiguous slot so node 11
// can persist them on the pending_clarification row (needed to resolve
// digit picks later).

const ctx = $('01 Parse + Authorize + Plan').first().json;
const aiResp = $input.first().json;

let slots = [];
let rawText = '';
try {
  const choice = (aiResp.choices || [])[0];
  rawText = choice && choice.message && choice.message.content ? choice.message.content : '';
  // Strip ```json fences if the model added them despite response_format.
  const stripped = rawText
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
  const parsed = JSON.parse(stripped);
  slots = Array.isArray(parsed.slots) ? parsed.slots : [];
} catch (e) {
  return [{
    json: {
      ...ctx,
      aiError: String(e),
      aiRawText: rawText,
      slots: [],
      needsClarification: true,
      clarificationText:
        'Не удалось разобрать сообщение. Пришли его в формате `0855-0955 [CODE] activity` или `20 мин activity`.',
      suggestedCategories: [],
    },
  }];
}

const threshold = parseFloat($env.AI_CONFIDENCE_THRESHOLD || '0.80');
let needsClarification = false;
let clarificationText = '';
let suggestedCategories = [];

function normalizeSuggested(arr) {
  return (arr || []).slice(0, 4).map(o =>
    typeof o === 'string'
      ? { code: o, name: '' }
      : { code: String(o.code || o), name: String(o.name || '') }
  );
}

if (slots.length === 0) {
  needsClarification = true;
  clarificationText = 'Не получилось распознать ни одного слота. Уточни время и активность, пожалуйста.';
} else {
  for (const s of slots) {
    if (s.needs_clarification === true || (typeof s.confidence === 'number' && s.confidence < threshold)) {
      needsClarification = true;
      suggestedCategories = normalizeSuggested(s.suggested_categories);
      const q = s.clarification_question || `Не уверен в категории слота: ${s.activity || ctx.text}`;
      clarificationText = `${q}` + (suggestedCategories.length
        ? `\n\nВыбери один вариант:\n` + suggestedCategories.map((o, i) => `${i + 1}. [${o.code}] ${o.name}`).join('\n') + `\n\nИли пришли новое уточнение свободным текстом.`
        : '');
      break;
    }
  }
}

for (const s of slots) {
  if (s.start_time && /^\d{1,2}:\d{2}$/.test(s.start_time)) {
    const [h, m] = s.start_time.split(':');
    s.start_time = `${h.padStart(2, '0')}:${m}`;
  }
  if (s.end_time && /^\d{1,2}:\d{2}$/.test(s.end_time)) {
    const [h, m] = s.end_time.split(':');
    s.end_time = `${h.padStart(2, '0')}:${m}`;
  }
  if (!s.slot_date) s.slot_date = ctx.todayDate;
  if (!s.classification_source) s.classification_source = 'ai';
  if (!s.emotional_mark) s.emotional_mark = 'N';
  s.duration_minutes = parseInt(s.duration_minutes, 10) || 0;
}

return [{
  json: {
    ...ctx,
    slots,
    needsClarification,
    clarificationText,
    suggestedCategories,
    rawAi: rawText,
  },
}];

// Fill missing start_time/end_time for duration-only slots, then prepare
// SQL strings for both the clarification path and the save path. All
// user-controlled values inline as a single JSONB literal.

const ctx = $('09 Process AI Response').first().json;
const lastEndRow = $input.first().json;
const lastEnd = lastEndRow && lastEndRow.last_end ? lastEndRow.last_end : null;

function toMinutes(t) {
  if (!t) return null;
  const m = /^([0-2]?\d):([0-5]\d)/.exec(t);
  if (!m) return null;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
}
function fromMinutes(total) {
  const h = Math.floor(total / 60);
  const m = total % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

let cursor = toMinutes(lastEnd);
for (const s of ctx.slots) {
  // Случай 1: только длительность — цепляем от cursor
  if (!s.start_time && s.duration_minutes > 0) {
    if (cursor === null) continue;
    s.start_time = fromMinutes(cursor);
    s.end_time = fromMinutes(cursor + s.duration_minutes);
    cursor += s.duration_minutes;
  }
// Случай 2: только end_time ("до HH:MM" или "HH:MM закончил X") — 
// start = cursor, duration = end - cursor (с обработкой полночи)
else if (!s.start_time && s.end_time && (!s.duration_minutes || s.duration_minutes === 0)) {
  if (cursor === null) continue;
  const endMin = toMinutes(s.end_time);
  if (endMin === null) continue;

  let adjustedEnd = endMin;
  if (endMin <= cursor) {
    // Через полночь: предполагаем что end_time = следующий день
    adjustedEnd = endMin + 24 * 60;
  }

  // Sanity check: > 8 часов = подозрительно, пропускаем
  if (adjustedEnd - cursor > 8 * 60) continue;

  s.start_time = fromMinutes(cursor);
  s.duration_minutes = adjustedEnd - cursor;
  // end_time оставляем как было (00:53), хотя факт. это уже следующий день
  cursor = endMin; // курсор обновляем на «новый день», 53 мин от полуночи
}
  // Случай 3: рефлексия (без времени, RX) — ставим текущее время как маркер
  else if (!s.start_time && !s.end_time && (!s.duration_minutes || s.duration_minutes === 0)) {
    const now = new Date(
      new Date().toLocaleString('en-US', { timeZone: $env.GENERIC_TIMEZONE || 'Europe/Warsaw' })
    );
    const nowTime = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    s.start_time = nowTime;
    s.end_time = nowTime;
    s.duration_minutes = 0;
  }
  // Случай 4: полный слот — обновляем cursor
  else if (s.start_time && s.end_time) {
    cursor = toMinutes(s.end_time);
  }
}

function jsonbLiteral(obj) {
  return `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;
}

// Pending path: persist the AI's slots as status='pending_clarification'
// and store the suggested_categories on the pending row so the resolve
// step can pick by digit without re-running the AI.
const pendingPayload = {
  chat_id: ctx.chatId,
  user_id: ctx.userId,
  message_id: ctx.messageId,
  text: ctx.text,
  date: ctx.todayDate,
  question: ctx.clarificationText || '',
  suggested_categories: ctx.suggestedCategories || [],
  slots: ctx.slots || [],
};

const pendingSql = `
WITH input AS (SELECT ${jsonbLiteral(pendingPayload)} AS d),
new_batch AS (
  INSERT INTO time_message_batches (
    telegram_chat_id, telegram_user_id, telegram_message_id,
    raw_text, batch_date, status
  )
  SELECT
    d->>'chat_id', d->>'user_id', d->>'message_id',
    d->>'text', (d->>'date')::date,
    'pending_clarification'
  FROM input
  RETURNING id
),
slot_rows AS (
  SELECT
    (s ->> 'slot_date')::date              AS slot_date,
    NULLIF(s ->> 'start_time', '')::time   AS start_time,
    NULLIF(s ->> 'end_time', '')::time     AS end_time,
    (s ->> 'duration_minutes')::int        AS duration_minutes,
    s ->> 'activity'                       AS activity,
    s ->> 'category_code'                  AS category_code,
    s ->> 'category_name'                  AS category_name,
    COALESCE(s ->> 'emotional_mark', 'N')  AS emotional_mark,
    NULLIF(s ->> 'confidence', '')::numeric AS confidence,
    s -> 'suggested_categories'            AS suggested_categories
  FROM input, jsonb_array_elements(input.d->'slots') AS s
  WHERE COALESCE((s ->> 'duration_minutes')::int, 0) >= 0
),
ins_slots AS (
  INSERT INTO time_slots (
    batch_id, slot_date, start_time, end_time,
    duration_minutes, activity, category_code, category_name,
    emotional_mark, confidence, classification_source,
    status, needs_clarification, suggested_categories
  )
  SELECT
    nb.id, sr.slot_date, sr.start_time, sr.end_time,
    sr.duration_minutes, sr.activity, sr.category_code, sr.category_name,
    sr.emotional_mark, sr.confidence, 'ai',
    'pending_clarification', TRUE, sr.suggested_categories
  FROM new_batch nb CROSS JOIN slot_rows sr
  RETURNING id
)
INSERT INTO time_pending_clarifications (
  batch_id, telegram_chat_id, telegram_user_id,
  original_text, question_text, suggested_categories, status
)
SELECT
  nb.id,
  (SELECT d->>'chat_id' FROM input),
  (SELECT d->>'user_id' FROM input),
  (SELECT d->>'text' FROM input),
  (SELECT d->>'question' FROM input),
  (SELECT d->'suggested_categories' FROM input),
  'pending'
FROM new_batch nb
RETURNING batch_id;
`;

return [{ json: { ...ctx, pendingSql } }];

